def evolve(state: str, offsets: list[int], t: int) -> str:
    n = len(state)

    # new[i] = XOR of old[(i + d) mod n], which is multiplication by
    # Q(x) = sum of x^((-d) mod n) in GF(2)[x] / (x^n - 1).
    # Offsets that reduce to the same exponent cancel in pairs.
    parity = {}
    for d in offsets:
        e = (-d) % n
        parity[e] = parity.get(e, 0) ^ 1
    exps = [e for e, p in parity.items() if p]

    mask = (1 << n) - 1

    def rotate(v: int, e: int) -> int:
        # Multiply v by x^e modulo x^n - 1 (cyclic shift toward higher indices).
        return ((v << e) | (v >> (n - e))) & mask

    def square(es: list[int]) -> list[int]:
        # Over GF(2), Q(x)^2 = Q(x^2), so squaring doubles each exponent.
        # Terms that land on the same exponent cancel.
        p = {}
        for e in es:
            f = (2 * e) % n
            p[f] = p.get(f, 0) ^ 1
        return [f for f, v in p.items() if v]

    # Bit i of cur holds the value of lamp i.
    cur = 0
    for i, ch in enumerate(state):
        if ch == '1':
            cur |= 1 << i

    # Q^(2^k) always has at most len(offsets) terms, so each step is cheap.
    # All powers of Q commute, so the order of application does not matter.
    power_exps = exps
    while t:
        if t & 1:
            new = 0
            for e in power_exps:
                new ^= rotate(cur, e)
            cur = new
        t >>= 1
        if t:
            power_exps = square(power_exps)

    return format(cur, f'0{n}b')[::-1]
